-- Generated by drizzle-kit (the snapshot is the generated one), plus hand-written backfills.
-- Phase 3 review fixes and Phase 4 (billing):
-- 1. consents.purpose (face_search | face_deletion, existing rows face_search); the current-consent
--    unique indexes now include it.
-- 2. subscriptions: period_start, auto-renew method (payment_method_gateway/_ref, never card
--    data; auto_renew_months 1 or 12), scheduled downgrade (pending_plan_id/_effective_at),
--    updated_at.
-- 3. payments: photographer_id (backfilled), nullable subscription_id, checkout_id or
--    renewal_period_end, failure_code, refunded_at, receipt_sent_at, updated_at; one open renewal
--    charge per period; one payment per checkout.
-- 4. New tables: checkout_sessions (checkouts and their Idempotency-Key store),
--    payment_webhook_events (verified webhooks, payload hash only), subscription_notices (lifecycle
--    emails sent once), subscription_events (audit trail).
CREATE TYPE "public"."billing_actor" AS ENUM('photographer', 'gateway', 'system', 'admin');--> statement-breakpoint
CREATE TYPE "public"."checkout_change_type" AS ENUM('new', 'renew', 'upgrade', 'downgrade');--> statement-breakpoint
CREATE TYPE "public"."checkout_status" AS ENUM('pending', 'completed', 'failed', 'expired');--> statement-breakpoint
CREATE TYPE "public"."consent_purpose" AS ENUM('face_search', 'face_deletion');--> statement-breakpoint
CREATE TYPE "public"."payment_event_type" AS ENUM('paid', 'failed', 'expired', 'refunded');--> statement-breakpoint
CREATE TYPE "public"."subscription_event_type" AS ENUM('created', 'activated', 'renewed', 'upgraded', 'downgrade_scheduled', 'downgrade_applied', 'auto_renew_enabled', 'auto_renew_canceled', 'renewal_failed', 'grace_started', 'expired', 'purged', 'payment_unapplied', 'payment_refunded');--> statement-breakpoint
CREATE TYPE "public"."subscription_notice_kind" AS ENUM('renewal_reminder', 'grace_started', 'expired', 'purge_warning');--> statement-breakpoint
CREATE TABLE "checkout_sessions" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"photographer_id" uuid NOT NULL,
	"subscription_id" uuid,
	"change_type" "checkout_change_type" NOT NULL,
	"plan_id" uuid NOT NULL,
	"from_plan_id" uuid,
	"method" "payment_method" NOT NULL,
	"months" integer,
	"amount_satang" integer NOT NULL,
	"vat_satang" integer NOT NULL,
	"proration_satang" integer,
	"proration_days" integer,
	"gateway" text,
	"status" "checkout_status" DEFAULT 'pending' NOT NULL,
	"idempotency_key" text NOT NULL,
	"request_sha256" text NOT NULL,
	"qr_payload" text,
	"redirect_url" text,
	"error_code" text,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone,
	CONSTRAINT "checkout_sessions_idempotency_unique" UNIQUE("photographer_id","idempotency_key"),
	CONSTRAINT "checkout_sessions_idempotency_key_format" CHECK ("checkout_sessions"."idempotency_key" ~ '^[!-~]{1,255}$'),
	CONSTRAINT "checkout_sessions_request_sha256_hex" CHECK ("checkout_sessions"."request_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "checkout_sessions_amounts_valid" CHECK ("checkout_sessions"."amount_satang" >= 0 AND "checkout_sessions"."vat_satang" >= 0 AND "checkout_sessions"."vat_satang" <= "checkout_sessions"."amount_satang" AND ("checkout_sessions"."proration_satang" IS NULL OR "checkout_sessions"."proration_satang" >= 0) AND ("checkout_sessions"."proration_days" IS NULL OR "checkout_sessions"."proration_days" >= 0)),
	CONSTRAINT "checkout_sessions_proration_for_upgrades" CHECK (("checkout_sessions"."change_type" = 'upgrade') = ("checkout_sessions"."proration_satang" IS NOT NULL) AND ("checkout_sessions"."proration_satang" IS NULL) = ("checkout_sessions"."proration_days" IS NULL)),
	CONSTRAINT "checkout_sessions_months_valid" CHECK ("checkout_sessions"."months" IS NULL OR "checkout_sessions"."months" BETWEEN 1 AND 36),
	CONSTRAINT "checkout_sessions_months_required" CHECK ("checkout_sessions"."months" IS NOT NULL OR ("checkout_sessions"."change_type" = 'upgrade' AND "checkout_sessions"."method" = 'promptpay')),
	CONSTRAINT "checkout_sessions_gateway_iff_charged" CHECK (("checkout_sessions"."amount_satang" > 0) = ("checkout_sessions"."gateway" IS NOT NULL) AND ("checkout_sessions"."gateway" IS NULL OR "checkout_sessions"."gateway" ~ '^[a-z0-9_]{1,32}$')),
	CONSTRAINT "checkout_sessions_free_is_completed" CHECK ("checkout_sessions"."amount_satang" > 0 OR "checkout_sessions"."status" = 'completed'),
	CONSTRAINT "checkout_sessions_finished_iff_final" CHECK (("checkout_sessions"."status" = 'pending') = ("checkout_sessions"."finished_at" IS NULL)),
	CONSTRAINT "checkout_sessions_error_iff_failed" CHECK (("checkout_sessions"."status" = 'failed') = ("checkout_sessions"."error_code" IS NOT NULL) AND ("checkout_sessions"."error_code" IS NULL OR "checkout_sessions"."error_code" ~ '^[A-Z][A-Z0-9_]{0,63}$'))
);
--> statement-breakpoint
CREATE TABLE "payment_webhook_events" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"gateway" text NOT NULL,
