	"verified_at" timestamp with time zone NOT NULL,
	"processed_at" timestamp with time zone,
	"payment_id" uuid,
	"error_code" text,
	CONSTRAINT "payment_webhook_events_event_unique" UNIQUE("gateway","event_ref"),
	CONSTRAINT "payment_webhook_events_gateway_format" CHECK ("payment_webhook_events"."gateway" ~ '^[a-z0-9_]{1,32}$'),
	CONSTRAINT "payment_webhook_events_event_ref_valid" CHECK (length("payment_webhook_events"."event_ref") BETWEEN 1 AND 255),
	CONSTRAINT "payment_webhook_events_payload_sha256_hex" CHECK ("payment_webhook_events"."payload_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "payment_webhook_events_amount_nonnegative" CHECK ("payment_webhook_events"."amount_satang" IS NULL OR "payment_webhook_events"."amount_satang" >= 0),
	CONSTRAINT "payment_webhook_events_error_code_format" CHECK ("payment_webhook_events"."error_code" IS NULL OR "payment_webhook_events"."error_code" ~ '^[a-z][a-z0-9_]{0,63}$')
);
--> statement-breakpoint
